function validate([nums1, nums2]) {
  for (const [name, nums] of [['nums1', nums1], ['nums2', nums2]]) {
    if (!Array.isArray(nums) || nums.length < 1 || nums.length > 9) return `${name} needs 1 to 9 digits.`;
    if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 9)) return `Each digit of ${name} is between 1 and 9.`;
    if (new Set(nums).size !== nums.length) return `The digits of ${name} must be distinct.`;
  }
  return null;
}

