function minNumber(nums1, nums2) {
  let best = Infinity;
  for (const a of nums1) {
    for (const b of nums2) {
      if (a === b) {
        best = Math.min(best, a);
      } else {
        const low = Math.min(a, b);
        const high = Math.max(a, b);
        best = Math.min(best, low * 10 + high);
      }
    }
  }
  return best;
}

