function minNumber(nums1, nums2) {
  // Try every positive integer in increasing order until one uses a digit from each array.
  for (let candidate = 1; ; candidate++) {
    const digits = String(candidate);
    const fromFirst = nums1.some(d => digits.includes(String(d)));
    const fromSecond = nums2.some(d => digits.includes(String(d)));
    if (fromFirst && fromSecond) return candidate;
  }
}

